const KEY='lohd-run-101-v2';
const fresh=()=>({unlocked:1,levels:{},coins:0,best:0,name:'นักวิ่งสาเกต',scores:[]});
function missionSet(level){const coinTarget=8+Math.floor(level/4)*2,type=level%2?'double':'safe',doubleTarget=2+Math.floor(level/7);return [{id:'finish',label:'วิ่งถึง Knowledge Gate'},{id:'coins',target:coinTarget,label:`เก็บเหรียญ ${coinTarget} เหรียญ`},type==='safe'?{id:'safe',label:'ผ่านด่านโดยไม่เสียหัวใจ'}:{id:'double',target:doubleTarget,label:`ดับเบิลจัมป์ ${doubleTarget} ครั้ง`}];}
function missionDone(m,s=state,won=false){if(m.id==='finish')return won;if(m.id==='coins')return s.coins>=m.target;if(m.id==='safe')return s.lives===3;if(m.id==='double')return s.doubleJumps>=m.target;return false}
let save=load(),active=0,raf=0,state=null,last=0,tutorialMode=false,tutorialStepIndex=0,tutorialJumps=0,tutorialRunTimer=0,tutorialStepTimer=0,tutorialFrame=0,tutorialBusy=false,stageIntroTimer=0;
function load(){try{return {...fresh(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{return fresh()}}
function persist(){localStorage.setItem(KEY,JSON.stringify(save));syncCloud()}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
const $=s=>document.querySelector(s);
function show(id){cancelAnimationFrame(raf);if(id!=='tutorial')tutorialMode=false;document.querySelectorAll('main>section').forEach(x=>x.classList.toggle('hidden',x.id!==id));if(id==='stages')renderStages();if(id==='passport')renderPassport();if(id==='leaderboard')renderBoard();switchMusic(id==='gameScreen'?'game':'menu');updateHome()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));
function updateHome(){const stars=Object.values(save.levels).reduce((n,x)=>n+(x.stars||0),0);$('#homeStars').textContent=`${stars}/60`;$('#homeCoins').textContent=save.coins;$('#homeStamps').textContent=`${Object.keys(save.levels).length}/20`;$('#continueBtn').textContent='เริ่มเล่น ▶';$('#homeName').textContent=save.name;const ni=Math.min(save.unlocked-1,19);$('#homeNext').textContent=`🎯 ด่านถัดไป: Discovery ${String(ni+1).padStart(2,'0')} • ${PLACES[ni][0]}`}
function renderStages(){const g=$('#stageGrid');g.innerHTML='';PLACES.forEach((p,i)=>{const d=save.levels[i],b=document.createElement('button');b.className='stage '+(d?'done':'');b.disabled=i+1>save.unlocked;b.innerHTML=`<span class="no">DISCOVERY ${String(i+1).padStart(2,'0')}</span><h3>${p[0]} • ${p[1]}</h3><div class="muted">${p[2]}</div><div class="stars">${d?'★'.repeat(d.stars)+'☆'.repeat(3-d.stars):b.disabled?'🔒':'☆☆☆'}</div>`;b.onclick=()=>start(i);g.append(b)})}
function renderPassport(){const g=$('#passportGrid');g.innerHTML='';PLACES.forEach((p,i)=>{const d=document.createElement('div');d.className='stamp '+(save.levels[i]?'got':'');d.innerHTML=save.levels[i]?`<div>✓<br><b>${p[0]}</b><br><small>${p[1]}</small></div>`:`<div>?</div>`;g.append(d)});$('#passportCount').textContent=`${Object.keys(save.levels).length} / 20 ตรา`}
function renderBoard(){let rows=[...save.scores].sort((a,b)=>b.score-a.score).slice(0,10);if(!rows.length)rows=[{name:'รอฮีโร่คนแรก',score:0,level:1}];$('#playerName').value=save.name;$('#scoreRows').innerHTML=rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.name)}</td><td>${r.score.toLocaleString()}</td><td>${r.level}</td></tr>`).join('')}
function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}
$('#saveName').onclick=()=>{save.name=$('#playerName').value.trim()||'นักวิ่งสาเกต';persist();updateHome();toast('บันทึกชื่อแล้ว')};$('#continueBtn').onclick=()=>start(Math.min(save.unlocked-1,19));
function openNameModal(){$('#homeNameInput').value=save.name;$('#nameModal').classList.remove('hidden');$('#homeNameInput').focus()}
function saveHomeName(){save.name=$('#homeNameInput').value.trim()||'นักวิ่งสาเกต';persist();updateHome();toast('บันทึกชื่อแล้ว');$('#nameModal').classList.add('hidden')}
