const TUTORIAL=[['เจอกองฟาง ต้องทำอะไร?','กองฟางเตี้ยอยู่บนพื้น — กระโดดข้ามด้วย Space / ↑','🪵','เจอกองฟาง → กดกระโดด ↑'],['เจอของสูง ต้องทำอะไร?','ของสูงต้องใช้แรงส่ง — กดกระโดดติดกัน 2 ครั้ง','📦','เจอของสูง → ดับเบิลจัมป์ ↑ ↑'],['เจอแผงกั้น ต้องทำอะไร?','แผงนี้ข้ามไม่ได้ — กด ↓ เพื่อสไลด์ลอดใต้แผง','🚧','เจอแผงสูง → กดสไลด์ ↓'],['เจอหยดน้ำ ต้องทำอะไร?','วิ่งเข้าเก็บเพื่อเติมหลอดน้ำ ป้องกันหัวใจลด','💧','เจอหยดน้ำ → วิ่งเก็บ 💧']];
function beginTutorial(){tutorialMode=true;tutorialStepIndex=0;tutorialJumps=0;tutorialBusy=false;show('tutorial');tutorialMode=true;$('#tutorialFish').className='tutorial-fish';clearInterval(tutorialRunTimer);clearTimeout(tutorialStepTimer);tutorialRunTimer=setInterval(()=>{if(!tutorialMode)return;const fish=$('#tutorialFish');if(!fish.classList.contains('jump')&&!fish.classList.contains('slide')&&!fish.classList.contains('exit'))fish.src=`${SPRITE_ROOT}/run/run${11+(tutorialFrame++%8)}.png`},105);renderTutorial()}
function renderTutorial(){const step=TUTORIAL[tutorialStepIndex],prop=$('#tutorialProp');tutorialJumps=0;tutorialBusy=false;clearTimeout(tutorialStepTimer);$('#tutorialStep').textContent=`สนามฝึก ${tutorialStepIndex+1} / ${TUTORIAL.length}`;$('#tutorialTitle').textContent=step[0];$('#tutorialText').textContent=step[1];prop.textContent=step[2];$('#tutorialCallout').textContent=step[3];prop.style.cursor=tutorialStepIndex===3?'pointer':'default';$('#tutorialJump').textContent=tutorialStepIndex===3?'💧 เก็บน้ำ':'⬆ กระโดด';$('#tutorialProgress').innerHTML=TUTORIAL.map((_,i)=>`<i class="${i<tutorialStepIndex?'done':''}"></i>`).join('');prop.classList.remove('approach');void prop.offsetWidth;prop.classList.add('approach');if(tutorialStepIndex===3)tutorialStepTimer=setTimeout(()=>tutorialAction('water'),2850)}
function tutorialAction(type){if(!tutorialMode)return false;const fish=$('#tutorialFish');if(tutorialStepIndex===3&&(type==='jump'||type==='slide'))type='water';if(tutorialBusy&&!(tutorialStepIndex===1&&type==='jump'&&tutorialJumps===1))return true;if(tutorialStepIndex===0&&type==='jump'){tutorialBusy=true;fish.classList.add('jump');tone(340,610);setTimeout(()=>{fish.classList.remove('jump');advanceTutorial()},420)}else if(tutorialStepIndex===1&&type==='jump'){tutorialJumps++;fish.classList.add('jump');fish.style.transform=`translateY(${-75-tutorialJumps*65}px) rotate(${-tutorialJumps*4}deg)`;tone(tutorialJumps===2?520:340,tutorialJumps===2?920:610);$('#tutorialText').textContent=tutorialJumps===1?'ดีมาก! กดกระโดดอีกครั้งเพื่อขึ้นให้สูงกว่าเดิม':'ดับเบิลจัมป์สำเร็จ!';if(tutorialJumps>=2){tutorialBusy=true;setTimeout(()=>{fish.style.transform='';fish.classList.remove('jump');advanceTutorial()},480)}}else if(tutorialStepIndex===2&&type==='slide'){tutorialBusy=true;fish.classList.add('slide');tone(190,70,.18,.035,'sawtooth');setTimeout(()=>{fish.classList.remove('slide');advanceTutorial()},560)}else if(tutorialStepIndex===3&&type==='water'){tutorialBusy=true;clearTimeout(tutorialStepTimer);playSfx('coin');for(let i=0;i<7;i++)setTimeout(()=>tone(380+i*35,650+i*30,.09,.018,'sine'),i*35);$('#tutorialProp').classList.remove('approach');$('#tutorialProp').textContent='✨';$('#tutorialText').textContent='เก็บน้ำสำเร็จ! หลอดน้ำจะช่วยรักษาหัวใจของปลาหลด';setTimeout(completeTutorial,800)}return true}
function advanceTutorial(){tutorialStepIndex++;renderTutorial()}
function completeTutorial(){clearInterval(tutorialRunTimer);clearTimeout(tutorialStepTimer);save.tutorialDone=true;persist();const fish=$('#tutorialFish');$('#tutorialTitle').textContent='พร้อมออกวิ่งแล้ว!';$('#tutorialText').textContent='จำไว้: ↑ กระโดด • ↑↑ ดับเบิลจัมป์ • ↓ สไลด์ • 💧 เติมน้ำ';$('#tutorialCallout').textContent='ออกจากห้องฝึก → ไปวิ่งในร้อยเอ็ด!';fish.classList.add('exit');setTimeout(()=>{tutorialMode=false;start(Math.min(save.unlocked-1,19))},1050)}
$('#tutorialBtn').onclick=beginTutorial;$('#tutorialJump').onclick=()=>tutorialAction('jump');$('#tutorialSlide').onclick=()=>tutorialAction('slide');$('#tutorialProp').onclick=()=>tutorialAction('water');
