const stageBackgrounds=STAGE_BACKGROUNDS.map(name=>{const img=new Image();img.decoding='async';img.src=`assets/backgrounds/${name}`;return img});
function measureGroundPad(img){img.groundPad=0;img.addEventListener('load',()=>{try{const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const cx=c.getContext('2d');cx.drawImage(img,0,0);const w=c.width,h=c.height,data=cx.getImageData(0,0,w,h).data;for(let y=h-1;y>=0;y--){for(let x=0;x<w;x+=4){if(data[(y*w+x)*4+3]>20){img.groundPad=(h-1-y)/h;return}}}}catch{}})}
const stageObstacleImages=STAGE_ASSET_KEYS.map(key=>{const jumpImg=sprite(`assets/obstacles/stages/${key}/jump.png`);measureGroundPad(jumpImg);return{jump:jumpImg,slide:sprite(`assets/obstacles/stages/${key}/slide.png`)}});
function currentBackground(){const img=stageBackgrounds[active];return img?.complete&&img.naturalWidth?img:fallbackBackground}
const audio={muted:false,current:'',menu:new Audio('assets/audio/music-menu.mp3'),game:new Audio('assets/audio/music-game.mp3'),coin:new Audio('assets/audio/coin-pickup.wav'),power:new Audio('assets/audio/power-pickup.mp3'),hit:new Audio('assets/audio/player-hit.mp3'),impact:new Audio('assets/audio/imp sound.mp3')};
audio.menu.loop=audio.game.loop=true;audio.menu.volume=.22;audio.game.volume=.28;audio.coin.volume=.42;audio.power.volume=.48;audio.hit.volume=.52;audio.impact.volume=.58;
Object.values(audio).filter(x=>x instanceof Audio).forEach(x=>x.preload='auto');
function switchMusic(name){if(audio.current===name&&!audio[name].paused)return;['menu','game'].forEach(k=>{if(k!==name){audio[k].pause();audio[k].currentTime=0}});audio.current=name;if(!audio.muted)audio[name].play().catch(()=>{})}
function playSfx(name){if(audio.muted)return;try{const s=audio[name].cloneNode();s.volume=audio[name].volume;s.play().catch(()=>{})}catch{}}
function playCoinSound(){playSfx('coin')}
let soundContext;function tone(from,to,duration=.12,volume=.045,type='sine'){if(audio.muted)return;try{soundContext??=new (window.AudioContext||window.webkitAudioContext)();const o=soundContext.createOscillator(),gain=soundContext.createGain(),now=soundContext.currentTime;o.type=type;o.frequency.setValueAtTime(from,now);o.frequency.exponentialRampToValueAtTime(to,now+duration);gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(.001,now+duration);o.connect(gain).connect(soundContext.destination);o.start(now);o.stop(now+duration)}catch{}}
$('#soundBtn').onclick=()=>{audio.muted=!audio.muted;$('#soundBtn').textContent=audio.muted?'🔇':'🔊';if(audio.muted){audio.menu.pause();audio.game.pause()}else switchMusic(audio.current||'menu');toast(audio.muted?'ปิดเสียงแล้ว':'เปิดเสียงแล้ว')};
addEventListener('pointerdown',()=>{if(!audio.muted&&audio.current)audio[audio.current].play().catch(()=>{})},{once:true});
function size(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0)}addEventListener('resize',size);
function showStageIntro(){const el=$('#stageIntro');if(!el)return;$('#stageIntroNum').textContent=`${active+1}/20`;$('#stageIntroName').textContent=PLACES[active][0];$('#stageIntroTag').textContent=PLACES[active][1];el.classList.remove('hidden');el.style.animation='none';void el.offsetWidth;el.style.animation='';clearTimeout(stageIntroTimer);stageIntroTimer=setTimeout(()=>el.classList.add('hidden'),3000)}
function start(level){hideOverlay();hideGateCountdown();active=Math.max(0,Math.min(19,level));show('gameScreen');size();const next=stageBackgrounds[Math.min(active+1,19)];if(next&&!next.complete)next.src=next.src;state={running:true,paused:false,t:0,distance:0,target:1450+active*70,speed:310+active*5,score:0,coins:0,lives:3,water:100,energy:0,power:0,giant:0,inv:0,spawn:0,safeSpawns:0,hits:0,hitStop:0,shake:0,nextDrip:0,doubleJumps:0,smashed:0,gateSeen:false,gateTimer:0,missions:missionSet(active),player:{x:110,y:0,vy:0,slide:false,jumpCount:0},items:[],particles:[]};updateHud();showStageIntro();last=performance.now();raf=requestAnimationFrame(loop)}
function ground(){return canvas.getBoundingClientRect().height-118}
function burst(kind,count=8){if(!state)return;for(let i=0;i<count;i++){const healing=kind==='heal';state.particles.push({kind,x:healing?108+Math.random()*64:125+Math.random()*34,y:healing?ground()-15-Math.random()*72:ground()-8-Math.random()*18,vx:healing?-18+Math.random()*36:(kind==='spark'?-80:-30)-Math.random()*130,vy:healing?-45-Math.random()*65:-35-Math.random()*110,life:healing?.8+Math.random()*.65:.35+Math.random()*.35,max:healing?1.45:.7,size:healing?3+Math.random()*4:2+Math.random()*5,phase:Math.random()*6.28})}}
function collectWaterEffect(){burst('water',18);for(let i=0;i<9;i++)state.particles.push({kind:'waterFly',x:126+Math.random()*35,y:ground()-38-Math.random()*45,vx:0,vy:0,tx:155+Math.random()*35,ty:24+Math.random()*10,life:.55+i*.035,max:.85,size:3+Math.random()*3,phase:Math.random()*6.28})}
function hitEffect(){state.hitStop=.095;state.shake=.3;burst('dust',24)}
function smashBurst(type,x,y){for(let i=0;i<24;i++)state.particles.push({kind:type==='sign'?'wood':'straw',x:x+Math.random()*50,y:y+Math.random()*55,vx:-180+Math.random()*360,vy:-100-Math.random()*250,life:.65+Math.random()*.55,max:1.2,size:3+Math.random()*8,spin:Math.random()*6})}
function jump(){if(tutorialMode){tutorialAction('jump');return}if(!state||!state.running||state.paused)return;const p=state.player;if(p.jumpCount<2){p.vy=-(610+Math.min(active*4,55));p.slide=false;p.jumpCount++;if(p.jumpCount===2)state.doubleJumps++;burst(p.jumpCount===2?'spark':'dust',p.jumpCount===2?14:9);tone(p.jumpCount===2?520:340,p.jumpCount===2?920:610,.13,p.jumpCount===2?.055:.04,'triangle');if(p.jumpCount===2)toast('ดับเบิลจัมป์! ✨')}}
function slide(on=true){if(tutorialMode){if(on)tutorialAction('slide');return}if(!state||!state.running)return;const p=state.player;if(on&&!p.slide){burst('slide',12);tone(190,70,.18,.035,'sawtooth')}p.slide=on;if(on&&p.y>0)p.vy+=180}
$('#jumpBtn').onpointerdown=e=>{e.preventDefault();jump()};$('#slideBtn').onpointerdown=e=>{e.preventDefault();slide(true)};$('#slideBtn').onpointerup=$('#slideBtn').onpointerleave=()=>slide(false);
addEventListener('keydown',e=>{if(['Space','ArrowUp'].includes(e.code)){e.preventDefault();jump()}if(['ArrowDown','KeyS'].includes(e.code)){e.preventDefault();slide(true)}if(e.code==='KeyP'||e.code==='Escape')pause()});addEventListener('keyup',e=>{if(['ArrowDown','KeyS'].includes(e.code))slide(false)});
$('#pauseBtn').onclick=pause;function pause(){if(!state||!state.running)return;state.paused=!state.paused;if(state.paused)overlay(`<h2>หยุดพัก</h2><p class="muted">พร้อมแล้วค่อยลุยต่อ</p><button class="btn primary" id="resume">วิ่งต่อ ▶</button><button class="btn" id="quit">กลับหน้าหลัก</button>`,()=>{$('#resume').onclick=()=>{hideOverlay();state.paused=false;last=performance.now()};$('#quit').onclick=()=>show('home')});else hideOverlay()}
function overlay(html,ready){$('#overlayPanel').innerHTML=html;$('#gameOverlay').classList.remove('hidden');ready?.()}function hideOverlay(){$('#gameOverlay').classList.add('hidden')}
function spawn(){const w=canvas.getBoundingClientRect().width,x=w+40,hazards=state.items.filter(o=>o.type==='rock'||o.type==='sign'||o.type==='creature'),latest=hazards.reduce((m,o)=>Math.max(m,o.x),-9999),minGap=Math.min(500,state.speed*(1.02+Math.max(0,4-active)*.025)),canHazard=x-latest>=minGap;let type,kind=null;const creatureChance=Math.min(.5,.2+active*.016);if(canHazard&&state.safeSpawns>=2){const r=Math.random();type=r<creatureChance?'creature':r<creatureChance+(1-creatureChance)*.55?'rock':'sign'}else if(state.lives<3&&!state.items.some(o=>o.type==='heart')&&Math.random()<.06){type='heart'}else{const r=Math.random();type=r<.43?'coin':r<.51?'water':r<.69?'rock':r<.86?'sign':r<.94?'power':'giant';if((type==='rock'||type==='sign')&&!canHazard)type=Math.random()<.72?'coin':'water'}if(type==='creature'){const pool=creaturePool();kind=pool[Math.floor(Math.random()*pool.length)]}if(type==='rock'||type==='sign'||type==='creature')state.safeSpawns=0;else state.safeSpawns++;state.items.push({type,kind,x,y:type==='coin'||type==='water'||type==='heart'?(Math.random()<.5?55:125):0,hit:false,phase:Math.random()*6.28})}
function obstacleMetrics(o){const g=ground();return o.type==='sign'?{x:o.x+8,y:g-326,w:112,h:274}:{x:o.x+7,y:g-104,w:108,h:104}}
function loop(now){if(!state)return;const dt=Math.min((now-last)/1000,.034);last=now;if(state.running&&!state.paused)tick(dt);draw();raf=requestAnimationFrame(loop)}
function tick(dt){const s=state,p=s.player,wasAir=p.y>1,runSpeed=s.speed*(s.power>0?1.45:1)*(s.giant>0?1.35:1);s.t+=dt;s.shake=Math.max(0,s.shake-dt);if(s.hitStop>0){s.hitStop=Math.max(0,s.hitStop-dt);return}s.water=Math.max(0,s.water-dt*(2.15+active*.03));if(s.water<25&&s.t>=s.nextDrip){tone(760,360,.16,.018,'sine');s.nextDrip=s.t+(s.water<10?.72:1.15)}if(s.water<=0&&s.inv<=0){s.lives--;s.hits++;s.water=55;s.inv=1.35;playSfx('hit');hitEffect();burst('water',18);toast('💧 น้ำหมด! เสียหัวใจ 1 ดวง');if(s.lives<=0)return finish(false)}s.distance+=runSpeed*dt/10;s.score+=Math.floor(dt*runSpeed/9);s.speed+=dt*1.2;s.spawn-=dt;p.vy+=1550*dt;p.y=Math.max(0,p.y-p.vy*dt);if(p.y===0&&p.vy>0){p.vy=0;p.jumpCount=0;if(wasAir)burst('dust',13)}s.inv=Math.max(0,s.inv-dt);s.power=Math.max(0,s.power-dt);s.giant=Math.max(0,s.giant-dt);if(s.power>0&&Math.random()<dt*15)burst('heal',1);else if(p.y===0&&Math.random()<dt*8)burst('dust',1);for(const q of s.particles){q.life-=dt;if(q.kind==='waterFly'){const pull=Math.min(1,dt*7.5);q.x+=(q.tx-q.x)*pull;q.y+=(q.ty-q.y)*pull}else{q.x+=q.vx*dt+(q.kind==='heal'?Math.sin(s.t*7+q.phase)*18*dt:0);q.y+=q.vy*dt;if(q.kind!=='heal')q.vy+=180*dt}q.spin=(q.spin||0)+dt*5} s.particles=s.particles.filter(q=>q.life>0);if(s.spawn<=0){spawn();s.spawn=.55+Math.random()*.65-Math.min(active*.012,.2)}
 for(const o of s.items){o.x-=runSpeed*dt;const scale=(s.giant>0?1.42:1)*1.28,pw=(p.slide?64:46)*scale,ph=(p.slide?32:72)*scale,py=ground()-p.y-ph,box=(o.type==='rock'||o.type==='sign')?obstacleMetrics(o):o.type==='creature'?creatureBox(o):{x:o.x,y:ground()-44-o.y,w:56,h:44};if(!o.hit&&box.x<105+pw&&box.x+box.w>105&&box.y<py+ph&&box.y+box.h>py){o.hit=true;if(o.type==='coin'){s.coins++;s.score+=100;s.energy=Math.min(100,s.energy+12);playCoinSound()}else if(o.type==='water'){s.water=Math.min(100,s.water+35);s.score+=80;collectWaterEffect();playSfx('coin');toast('💧 เติมน้ำ +35')}else if(o.type==='heart'){s.lives=Math.min(3,s.lives+1);s.score+=150;burst('heal',30);playSfx('power');toast('❤️ ได้หัวใจคืนมา 1 ดวง!')}else if(o.type==='power'){s.power=7;s.energy=0;s.score+=250;burst('heal',34);playSfx('power');toast('💚 พลังฟื้นฟู! แสงฮีลทำงาน 7 วินาที')}else if(o.type==='giant'){s.giant=8;s.score+=300;burst('spark',26);playSfx('power');toast('💙 พลังยักษ์สปีด! วิ่งเร็วขึ้นและชนสิ่งกีดขวางได้ 8 วินาที')}else if(s.giant>0){s.score+=180;smashBurst(o.type,o.x,box.y);playSfx('impact')}else if(s.inv<=0){s.lives--;s.hits++;s.inv=1.5;s.energy=Math.max(0,s.energy-25);hitEffect();playSfx('hit');if(s.lives<=0)return finish(false)}}}s.items=s.items.filter(o=>o.x>-110&&!o.hit);if(s.energy>=100&&s.power<=0){s.power=7;s.energy=0;burst('heal',34);playSfx('power');toast('💚 Energy เต็ม — พลังฟื้นฟูทำงาน!')}if(s.distance>=s.target&&!s.gateSeen){s.gateSeen=true;s.gateTimer=5;showGateCountdown()}if(s.gateTimer>0){s.gateTimer-=dt;if(s.gateTimer<=0){s.gateTimer=0;hideGateCountdown();gate()}else updateGateCountdown(s.gateTimer)}updateHud()}
function updateHud(){if(!state)return;$('#hearts').textContent='❤️'.repeat(state.lives)+'🖤'.repeat(3-state.lives);$('#waterFill').style.width=state.water+'%';$('#waterFill').style.background=state.water<28?'linear-gradient(90deg,#ff6b58,#ffb24d)':'linear-gradient(90deg,#1a8cff,#76eaff)';$('#coinHud').textContent=state.coins;$('#scoreHud').textContent=state.score;const timed=state.giant>0?state.giant/8*100:state.power>0?state.power/7*100:state.energy;$('#energyFill').style.width=timed+'%';$('#energyFill').style.background=state.giant>0?'linear-gradient(90deg,#2d8cff,#8de9ff)':state.power>0?'linear-gradient(90deg,#32d66b,#a8ff78)':'#55e6e6';$('#stageHud').textContent=`${active+1}/20 • ${PLACES[active][1]} • ${Math.min(100,Math.floor(state.distance/state.target*100))}%${state.power>0?' • 💚 HEAL':''}${state.giant>0?' • 💙 GIANT x1.35':''}`}
function showGateCountdown(){const el=$('#gateCountdown');if(el)el.classList.remove('hidden');updateGateCountdown(5,true)}
function updateGateCountdown(t,force){const el=$('#gateCountdownNum'),n=Math.max(1,Math.ceil(t));if(el&&(force||el.textContent!==String(n))){el.textContent=n;tone(n<=1?300:420,n<=1?900:520,n<=1?.22:.08,n<=1?.06:.035)}}
function hideGateCountdown(){const el=$('#gateCountdown');if(el)el.classList.add('hidden')}
function gate(){state.running=false;hideGateCountdown();const q=QUESTIONS[active];overlay(`<div class="eyebrow">KNOWLEDGE GATE • ด่าน ${active+1}/20</div><h2>${q[0]}</h2><p class="muted">คำถามประจำอำเภอ${PLACES[active][0]} — ตอบถูกเพื่อรับตรา Saket Passport</p><div class="answers">${q[1].map((a,i)=>`<button class="answer" data-a="${i}">${a}</button>`).join('')}</div>`,()=>document.querySelectorAll('.answer').forEach(b=>b.onclick=()=>{document.querySelectorAll('.answer').forEach(x=>x.disabled=true);const ok=+b.dataset.a===q[2];b.classList.add(ok?'good':'bad');if(ok){state.score+=500;setTimeout(()=>finish(true),650)}else{document.querySelector(`[data-a="${q[2]}"]`).classList.add('good');setTimeout(()=>gate(),950)}}))}
function finishLegacy(won){state.running=false;const stars=won?(state.lives===3?3:state.lives===2?2:1):0,total=state.score+(won?state.lives*200:0);if(won){const old=save.levels[active];save.levels[active]={stars:Math.max(stars,old?.stars||0),score:Math.max(total,old?.score||0)};save.unlocked=Math.min(20,Math.max(save.unlocked,active+2));save.coins+=state.coins}save.best=Math.max(save.best,total);save.scores.push({name:save.name,score:total,level:active+1,date:Date.now()});save.scores=save.scores.sort((a,b)=>b.score-a.score).slice(0,20);persist();const action=won?'WT_1.png':'lose_1.png';overlay(`<img src="${SPRITE_ROOT}/actions/${action}" alt="${won?'ชนะ':'แพ้'}" style="width:180px;max-height:155px;object-fit:contain"><div class="eyebrow">${won?'DISCOVERY COMPLETE':'TRY AGAIN'}</div><h2>${won?'ประทับตราสำเร็จ! 🎉':'หมดแรงแล้ว!'}</h2><p>${PLACES[active][0]} • ${PLACES[active][1]}</p><div class="result-grid"><div><b>${total}</b>คะแนน</div><div><b>${state.coins}</b>เหรียญ</div><div><b>${won?'★'.repeat(stars):'—'}</b>ดาว</div></div><button class="btn primary" id="again">${won&&active<19?'ด่านถัดไป ▶':'ลองอีกครั้ง'}</button><button class="btn" id="toMap">แผนที่ด่าน</button>`,()=>{$('#again').onclick=()=>start(won&&active<19?active+1:active);$('#toMap').onclick=()=>show('stages')})}
function drawFieldObstacle(o,oy){ctx.save();ctx.shadowColor='#1f160bb0';ctx.shadowBlur=10;ctx.shadowOffsetY=5;const floor=ground();if(o.type==='rock'){const x=o.x,y=floor-50;ctx.fillStyle='#74451f';ctx.strokeStyle='#3a210f';ctx.lineWidth=4;ctx.beginPath();ctx.roundRect(x-3,y+19,49,31,8);ctx.fill();ctx.stroke();ctx.fillStyle='#e6ad3d';ctx.beginPath();ctx.arc(x+20,y+25,22,0,7);ctx.fill();ctx.stroke();ctx.strokeStyle='#fff1a0';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x+20,y+25,13,.2,5.4);ctx.stroke();ctx.strokeStyle='#9e671f';ctx.lineWidth=2;for(let i=-1;i<3;i++){ctx.beginPath();ctx.moveTo(x+4+i*10,y+9);ctx.lineTo(x+17+i*9,y+41);ctx.stroke()}ctx.fillStyle='#3a210f55';ctx.beginPath();ctx.ellipse(x+20,floor+2,28,5,0,0,7);ctx.fill()}else if(o.type==='sign'){const x=o.x,y=floor-108;ctx.strokeStyle='#382516';ctx.lineWidth=9;ctx.lineCap='butt';ctx.beginPath();ctx.moveTo(x+2,y);ctx.lineTo(x+2,floor);ctx.moveTo(x+43,y);ctx.lineTo(x+43,floor);ctx.stroke();ctx.strokeStyle='#d8a84e';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x+2,y);ctx.lineTo(x+2,floor);ctx.moveTo(x+43,y);ctx.lineTo(x+43,floor);ctx.moveTo(x-4,y+5);ctx.lineTo(x+49,y+5);ctx.stroke();ctx.fillStyle='#f1c94c';ctx.strokeStyle='#604018';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x+3,y+8);ctx.lineTo(x+43,y+8);ctx.lineTo(x+37,y+49);ctx.quadraticCurveTo(x+22,y+62,x+8,y+49);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#fff0a0';ctx.lineWidth=2;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(x+9+i*7,y+14);ctx.lineTo(x+12+i*5,y+46);ctx.stroke()}ctx.fillStyle='#2e1b0d88';ctx.beginPath();ctx.ellipse(x+22,floor+2,31,5,0,0,7);ctx.fill()}else{ctx.shadowColor='#42ff7c';ctx.shadowBlur=22;const glow=ctx.createRadialGradient(o.x+19,oy+19,3,o.x+19,oy+19,23);glow.addColorStop(0,'#eaffd8');glow.addColorStop(.45,'#62f58d');glow.addColorStop(1,'#138c47');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(o.x+19,oy+19,22,0,7);ctx.fill();ctx.strokeStyle='#caffb3';ctx.lineWidth=2;ctx.stroke();ctx.font='28px serif';ctx.fillText('➤',o.x+5,oy+30)}ctx.restore()}
function drawBluePower(o,oy){ctx.save();ctx.shadowColor='#35bfff';ctx.shadowBlur=28;const glow=ctx.createRadialGradient(o.x+25,oy+25,3,o.x+25,oy+25,30);glow.addColorStop(0,'#efffff');glow.addColorStop(.45,'#55cfff');glow.addColorStop(1,'#155fc4');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(o.x+25,oy+25,29,0,7);ctx.fill();ctx.strokeStyle='#b9f3ff';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 25px system-ui';ctx.fillText('⬆',o.x+11,oy+34);ctx.restore()}
