function drawWaterDrop(o,oy){ctx.save();ctx.translate(o.x+25,oy+25);const pulse=1+Math.sin(state.t*6+o.x)*.08;ctx.scale(pulse,pulse);ctx.shadowColor='#29cfff';ctx.shadowBlur=24;const glow=ctx.createLinearGradient(0,-27,0,27);glow.addColorStop(0,'#dfffff');glow.addColorStop(.38,'#55dfff');glow.addColorStop(1,'#157ee8');ctx.fillStyle=glow;ctx.strokeStyle='#e8ffff';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-27);ctx.bezierCurveTo(-5,-15,-21,1,-21,12);ctx.bezierCurveTo(-21,27,21,27,21,12);ctx.bezierCurveTo(21,1,5,-15,0,-27);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffffffaa';ctx.beginPath();ctx.ellipse(-7,5,4,8,.45,0,7);ctx.fill();ctx.restore()}
function drawDirectionCue(o){const jump=o.type==='rock',x=o.x+(jump?61:64),y=jump?ground()-59:ground()-258,dir=jump?-1:1;ctx.save();ctx.translate(x,y);ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowColor='#091725cc';ctx.shadowBlur=7;ctx.strokeStyle='#061929';ctx.lineWidth=14;ctx.beginPath();ctx.moveTo(0,-dir*17);ctx.lineTo(0,dir*14);ctx.moveTo(-13,dir*3);ctx.lineTo(0,dir*18);ctx.lineTo(13,dir*3);ctx.stroke();ctx.shadowColor=jump?'#ffe260':'#58e7ff';ctx.shadowBlur=12;ctx.strokeStyle=jump?'#fff0a0':'#d9fbff';ctx.lineWidth=7;ctx.stroke();ctx.restore()}
