const CREATURES={chicken:{w:78,h:66},frog:{w:70,h:56},goose:{w:92,h:82},dragonfly:{w:54,h:54},snake:{w:150,h:54},buffalo:{w:118,h:168,double:true}};
function creaturePool(){const pool=['chicken'];if(active>=2)pool.push('frog');if(active>=5)pool.push('goose');if(active>=7)pool.push('dragonfly');if(active>=10)pool.push('snake');if(active>=14)pool.push('buffalo');return pool}
function creatureBox(o){const g=ground(),c=CREATURES[o.kind];if(o.kind==='frog'){const hopT=(state.t*1.4+o.phase)%1,hop=Math.max(0,Math.sin(hopT*Math.PI))*32;return{x:o.x+6,y:g-c.h-hop,w:c.w,h:c.h+hop,mode:'jump',hop}}if(o.kind==='dragonfly'){const flyT=state.t*(2*Math.PI/2.3)+o.phase,f=(Math.sin(flyT)+1)/2,high=f>.55;return high?{x:o.x+4,y:g-266,w:c.w,h:214,mode:'slide',f}:{x:o.x+4,y:g-c.h,w:c.w,h:c.h,mode:'jump',f}}return{x:o.x+6,y:g-c.h,w:c.w-12,h:c.h,mode:c.double?'doublejump':'jump'}}
function drawArrowGlyph(x,y,dir,color){ctx.save();ctx.translate(x,y);ctx.lineCap='round';ctx.lineJoin='round';ctx.shadowColor='#091725cc';ctx.shadowBlur=7;ctx.strokeStyle='#061929';ctx.lineWidth=14;ctx.beginPath();ctx.moveTo(0,-dir*17);ctx.lineTo(0,dir*14);ctx.moveTo(-13,dir*3);ctx.lineTo(0,dir*18);ctx.lineTo(13,dir*3);ctx.stroke();ctx.shadowColor=color;ctx.shadowBlur=12;ctx.strokeStyle=dir<0?'#fff0a0':'#d9fbff';ctx.lineWidth=7;ctx.stroke();ctx.restore()}
