function drawChicken(o,box){const x=box.x,y=box.y,w=box.w,h=box.h,walk=Math.sin(state.t*11+o.phase)*5;ctx.fillStyle='#3a210f88';ctx.beginPath();ctx.ellipse(x+w/2,y+h+2,w*.32,5,0,0,7);ctx.fill();ctx.strokeStyle='#e08a2e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+w*.38,y+h-6);ctx.lineTo(x+w*.38+walk,y+h+8);ctx.moveTo(x+w*.62,y+h-6);ctx.lineTo(x+w*.62-walk,y+h+8);ctx.stroke();ctx.fillStyle='#f5efe0';ctx.strokeStyle='#8a6a3f';ctx.lineWidth=2.5;ctx.beginPath();ctx.ellipse(x+w*.48,y+h*.62,w*.42,h*.36,0,0,7);ctx.fill();ctx.stroke();ctx.beginPath();ctx.ellipse(x+w*.24,y+h*.34,w*.22,h*.22,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#d6482f';ctx.beginPath();ctx.moveTo(x+w*.18,y+h*.16);ctx.quadraticCurveTo(x+w*.24,y-4,x+w*.30,y+h*.16);ctx.quadraticCurveTo(x+w*.24,y+h*.24,x+w*.18,y+h*.16);ctx.fill();ctx.fillStyle='#e6912e';ctx.beginPath();ctx.moveTo(x+w*.08,y+h*.34);ctx.lineTo(x-2,y+h*.36);ctx.lineTo(x+w*.08,y+h*.42);ctx.closePath();ctx.fill();ctx.fillStyle='#241a10';ctx.beginPath();ctx.arc(x+w*.18,y+h*.30,2.2,0,7);ctx.fill();ctx.strokeStyle='#8a6a3f';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+w*.78,y+h*.4);ctx.quadraticCurveTo(x+w*.95,y+h*.2,x+w*.9,y+h*.02);ctx.stroke()}
function drawFrog(o,box){const x=box.x,y=box.y,w=box.w,h=box.h,hop=box.hop||0,squat=1-Math.min(1,hop/32)*.4,leg=hop>10?-6:6;ctx.fillStyle='#2c5a1f88';ctx.beginPath();ctx.ellipse(x+w/2,ground()+2,w*.34,5,0,0,7);ctx.fill();ctx.fillStyle='#4f9e3a';ctx.strokeStyle='#2c5a1f';ctx.lineWidth=2.5;ctx.beginPath();ctx.ellipse(x+w/2,y+h*.62,w*.44,h*.4*squat,0,0,7);ctx.fill();ctx.stroke();ctx.beginPath();ctx.ellipse(x+w*.36,y+h*.18,w*.16,h*.16,0,0,7);ctx.fill();ctx.stroke();ctx.beginPath();ctx.ellipse(x+w*.64,y+h*.18,w*.16,h*.16,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(x+w*.36,y+h*.12,5,0,7);ctx.arc(x+w*.64,y+h*.12,5,0,7);ctx.fill();ctx.fillStyle='#1a1a1a';ctx.beginPath();ctx.arc(x+w*.36,y+h*.12,2,0,7);ctx.arc(x+w*.64,y+h*.12,2,0,7);ctx.fill();ctx.strokeStyle='#2c5a1f';ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x+w*.14,y+h*.7);ctx.quadraticCurveTo(x+w*.02,y+h*.8+leg,x-4,y+h+leg);ctx.stroke();ctx.beginPath();ctx.moveTo(x+w*.86,y+h*.7);ctx.quadraticCurveTo(x+w*.98,y+h*.8+leg,x+w+4,y+h+leg);ctx.stroke()}
function drawGoose(o,box){const x=box.x,y=box.y,w=box.w,h=box.h,walk=Math.sin(state.t*9+o.phase)*5,flap=Math.sin(state.t*13+o.phase)*8;ctx.fillStyle='#3a210f88';ctx.beginPath();ctx.ellipse(x+w*.42,y+h+2,w*.3,5,0,0,7);ctx.fill();ctx.strokeStyle='#e6912e';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(x+w*.32,y+h-8);ctx.lineTo(x+w*.32+walk,y+h+9);ctx.moveTo(x+w*.52,y+h-8);ctx.lineTo(x+w*.52-walk,y+h+9);ctx.stroke();ctx.fillStyle='#f5f5f0';ctx.strokeStyle='#b7b7a8';ctx.lineWidth=2.5;ctx.beginPath();ctx.ellipse(x+w*.42,y+h*.62,w*.4,h*.34,0,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#dcdcd2';ctx.beginPath();ctx.ellipse(x+w*.36,y+h*.55,w*.24,h*.18+flap*.3,-.3,0,7);ctx.fill();ctx.strokeStyle='#f5f5f0';ctx.lineWidth=9;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x+w*.72,y+h*.5);ctx.quadraticCurveTo(x+w*.9,y+h*.15,x+w*.86,y-h*.05);ctx.stroke();ctx.fillStyle='#f5f5f0';ctx.beginPath();ctx.arc(x+w*.86,y-h*.05,10,0,7);ctx.fill();ctx.fillStyle='#e6912e';ctx.beginPath();ctx.moveTo(x+w*.94,y-h*.07);ctx.lineTo(x+w+8,y-h*.05);ctx.lineTo(x+w*.94,y-h*.01);ctx.closePath();ctx.fill();ctx.fillStyle='#1a1a1a';ctx.beginPath();ctx.arc(x+w*.88,y-h*.08,1.8,0,7);ctx.fill()}
