function drawSnakeCreature(o,box){const x=box.x,y=box.y,w=box.w,h=box.h,g=ground(),segN=6,pts=[];for(let i=0;i<=segN;i++)pts.push([x+4+(w-24)*(i/segN),y+h*.5+Math.sin(i*1.4+state.t*3+o.phase)*h*.28]);ctx.fillStyle='#2c5a1f88';ctx.beginPath();ctx.ellipse(x+w/2,g+2,w*.4,5,0,0,7);ctx.fill();ctx.strokeStyle='#5a8a2f';ctx.lineWidth=h*.6;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(pts[0][0],pts[0][1]);for(const p of pts.slice(1))ctx.lineTo(p[0],p[1]);ctx.stroke();const head=pts[segN];ctx.fillStyle='#5a8a2f';ctx.beginPath();ctx.arc(head[0],head[1],h*.36,0,7);ctx.fill();ctx.fillStyle='#1a1a1a';ctx.beginPath();ctx.arc(head[0]-3,head[1]-4,2,0,7);ctx.fill();ctx.strokeStyle='#d6482f';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(head[0]+8,head[1]);ctx.lineTo(head[0]+16,head[1]-3);ctx.moveTo(head[0]+8,head[1]);ctx.lineTo(head[0]+16,head[1]+3);ctx.stroke()}
