function draw(){
 const w=canvas.getBoundingClientRect().width,h=canvas.getBoundingClientRect().height,g=ground();ctx.clearRect(0,0,w,h);ctx.save();if(state.shake>0){const force=state.shake/.3*8;ctx.translate((Math.random()-.5)*force,(Math.random()-.5)*force)}
 const bg=currentBackground();if(bg.complete&&bg.naturalWidth){const dh=g+16,dw=bg.naturalWidth*(dh/bg.naturalHeight),travel=state.distance*1.35,tileNo=Math.floor(travel/dw),off=-(travel%dw),overlap=1.5;for(let i=-1;i<Math.ceil(w/dw)+2;i++){const tile=tileNo+i,x=off+i*dw;ctx.save();ctx.beginPath();ctx.rect(x-overlap,0,dw+overlap*2,dh);ctx.clip();if(Math.abs(tile)%2===1){ctx.translate(x+dw+overlap,0);ctx.scale(-1,1);ctx.drawImage(bg,0,0,dw+overlap,dh)}else ctx.drawImage(bg,x-overlap,0,dw+overlap,dh);ctx.restore()}}else{const sky=ctx.createLinearGradient(0,0,0,g);sky.addColorStop(0,'#55cbea');sky.addColorStop(1,'#e8d66f');ctx.fillStyle=sky;ctx.fillRect(0,0,w,g)}
 const haze=ctx.createLinearGradient(0,g-90,0,g+10);haze.addColorStop(0,'#f7db6955');haze.addColorStop(1,'#416d2600');ctx.fillStyle=haze;ctx.fillRect(0,g-90,w,100);
 const road=ctx.createLinearGradient(0,g,0,h);road.addColorStop(0,'#b77a39');road.addColorStop(.35,'#8b552d');road.addColorStop(1,'#50321f');ctx.fillStyle=road;ctx.fillRect(0,g,w,h-g);ctx.fillStyle='#e0b75d';ctx.fillRect(0,g,w,8);ctx.fillStyle='#597f29';ctx.fillRect(0,g-7,w,9);
 ctx.globalAlpha=.24;ctx.strokeStyle='#f6d48a';ctx.lineWidth=2;for(let i=0;i<8;i++){const y=g+17+i*14,shift=(state.distance*(8+i*1.3))%90;ctx.setLineDash([38,52]);ctx.lineDashOffset=-shift;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.setLineDash([]);ctx.globalAlpha=1;
 for(let x=-30-(state.distance*9%55);x<w;x+=55){ctx.fillStyle='#c9984e';ctx.beginPath();ctx.ellipse(x,g+35,15,4,0,0,7);ctx.fill()}
 for(const q of state.particles){const a=Math.max(0,q.life/q.max);ctx.globalAlpha=a;ctx.fillStyle=q.kind==='water'||q.kind==='waterFly'?'#55dfff':q.kind==='heal'?'#8dffad':q.kind==='spark'?'#fff07b':q.kind==='wood'?'#7b421f':q.kind==='straw'?'#e2ad38':q.kind==='slide'?'#ffe2a1':'#dfb86f';ctx.save();ctx.translate(q.x,q.y);ctx.rotate(q.kind==='heal'?0:q.spin||0);ctx.beginPath();if(q.kind==='heal'){ctx.shadowColor='#35f27a';ctx.shadowBlur=12;ctx.roundRect(-q.size*.45,-q.size*1.7,q.size*.9,q.size*3.4,q.size*.4);ctx.roundRect(-q.size*1.7,-q.size*.45,q.size*3.4,q.size*.9,q.size*.4)}else if(q.kind==='water'||q.kind==='waterFly'){ctx.shadowColor='#29cfff';ctx.shadowBlur=q.kind==='waterFly'?16:10;ctx.ellipse(0,0,q.size*.75,q.size*1.35,0,0,7)}else if(q.kind==='wood')ctx.roundRect(-q.size*1.8,-q.size*.35,q.size*3.6,q.size*.7,2);else if(q.kind==='straw')ctx.rect(-q.size*1.4,-1,q.size*2.8,2);else if(q.kind==='slide')ctx.ellipse(0,0,q.size*2,q.size*.55,-.25,0,7);else ctx.arc(0,0,q.size,0,7);ctx.fill();ctx.restore()}ctx.globalAlpha=1;
 const p=state.player;ctx.fillStyle='#24160d55';ctx.beginPath();ctx.ellipse(140,g+5,Math.max(18,48-p.y*.08),7,0,0,7);ctx.fill();if(p.slide){ctx.strokeStyle='#fff3bb88';ctx.lineWidth=3;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(30-i*14,g-24-i*7);ctx.lineTo(95-i*5,g-24-i*7);ctx.stroke()}}
 for(const o of state.items){const oy=o.type==='sign'?g-350:o.type==='rock'?g-122:g-44-o.y;if(o.type==='coin'&&coinImage.complete){ctx.save();ctx.translate(o.x+27,oy+27);const pulse=1+Math.sin(state.t*7+o.x)*.08;ctx.scale(pulse,pulse);ctx.shadowColor='#ffdd45';ctx.shadowBlur=19;ctx.beginPath();ctx.arc(0,0,28,0,7);ctx.clip();ctx.drawImage(coinImage,-28,-28,56,56);ctx.restore();ctx.strokeStyle='#fff2a2';ctx.lineWidth=3;ctx.beginPath();ctx.arc(o.x+27,oy+27,28,0,7);ctx.stroke()}else if(o.type==='water')drawWaterDrop(o,oy);else if(o.type==='heart')drawHeartPickup(o,oy);else if(o.type==='giant')drawBluePower(o,oy);else if(o.type==='sign')drawStageObstacle(o,'slide');else if(o.type==='rock')drawStageObstacle(o,'jump');else if(o.type==='creature')drawCreature(o);else drawFieldObstacle(o,oy);if(o.type==='rock'||o.type==='sign')drawDirectionCue(o)}
 const giantScale=(state.giant>0?1.42:1)*1.28,py=g-p.y-(p.slide?32:72)*giantScale;let frame;if(state.inv>.9)frame=actionFrames.hit;else if(p.slide)frame=slideFrames[Math.floor(state.t*12)%slideFrames.length];else if(p.y>1){const ratio=Math.max(0,Math.min(.999,(p.vy+650)/1300));frame=jumpFrames[Math.floor(ratio*jumpFrames.length)]}else frame=runFrames[Math.floor(state.t*10)%runFrames.length];ctx.globalAlpha=state.inv>0&&Math.floor(state.inv*12)%2?0.3:1;ctx.save();ctx.translate(142,py+(p.slide?34:44)*giantScale);const ratio=frame?.naturalWidth&&frame?.naturalHeight?frame.naturalWidth/frame.naturalHeight:1,cw=(p.slide?112:Math.min(112,106*ratio))*giantScale,ch=(p.slide?86:106)*giantScale;ctx.shadowColor=state.giant>0?'#45c8ff':state.power>0?'#42ff7c':'#23150d55';ctx.shadowBlur=state.giant>0||state.power>0?22:9;ctx.shadowOffsetY=6;if(state.water<25)ctx.filter=`saturate(${.48+state.water/100}) brightness(${.78+state.water/180})`;if(frame?.complete&&frame.naturalWidth)ctx.drawImage(frame,-cw/2,-ch/2,cw,ch);else{ctx.font='72px serif';ctx.fillText('🐟',-34,25)}ctx.filter='none';if(state.water<25){ctx.fillStyle='#79e9ff';ctx.shadowColor='#28bfff';ctx.shadowBlur=8;for(let i=0;i<2;i++){const sx=34+i*12,sy=-28+(state.t*35+i*15)%38;ctx.beginPath();ctx.ellipse(sx,sy,3,6,.25,0,7);ctx.fill()}}ctx.restore();ctx.globalAlpha=1;
 if(state.giant>0){ctx.strokeStyle='#55cfff';ctx.lineWidth=5;ctx.shadowColor='#2d8cff';ctx.shadowBlur=18;ctx.beginPath();ctx.arc(140,py+38*giantScale,(58+Math.sin(state.t*10)*3)*giantScale,0,7);ctx.stroke();ctx.shadowBlur=0}ctx.restore();
 if(state.water<40){const danger=state.water<25,pulse=.35+Math.sin(state.t*(danger?7:4))*.1,edge=ctx.createRadialGradient(w/2,h/2,Math.min(w,h)*.27,w/2,h/2,Math.max(w,h)*.68);edge.addColorStop(.45,'transparent');edge.addColorStop(1,danger?`rgba(255,116,42,${pulse})`:`rgba(53,200,255,${pulse*.55})`);ctx.fillStyle=edge;ctx.fillRect(0,0,w,h);ctx.strokeStyle=danger?'#ff9b4aaa':'#66ddff77';ctx.lineWidth=danger?7:5;ctx.beginPath();for(let x=0;x<=w;x+=18){const y=8+Math.sin(x*.035+state.t*5)*4;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}
}
function renderMissionHud(){const box=$('#missionHud');if(!box||!state)return;box.innerHTML=state.missions.map(m=>{const done=missionDone(m,state,false),progress=m.id==='coins'?` ${Math.min(state.coins,m.target)}/${m.target}`:m.id==='double'?` ${Math.min(state.doubleJumps,m.target)}/${m.target}`:'';return `<div class="mission-line ${done?'done':''}"><i>${done?'✓':'☆'}</i><span>${m.label}${progress}</span></div>`}).join('')}
setInterval(()=>{if(state)renderMissionHud()},250);
function finish(won){state.running=false;const results=state.missions.map(m=>({...m,done:missionDone(m,state,won)})),stars=won?results.filter(m=>m.done).length:0,total=state.score+(won?state.lives*200:0);if(won){const old=save.levels[active];save.levels[active]={stars:Math.max(stars,old?.stars||0),score:Math.max(total,old?.score||0)};save.unlocked=Math.min(20,Math.max(save.unlocked,active+2));save.coins+=state.coins}save.best=Math.max(save.best,total);save.scores.push({name:save.name,score:total,level:active+1,date:Date.now()});save.scores=save.scores.sort((a,b)=>b.score-a.score).slice(0,20);persist();const action=won?'WT_1.png':'lose_1.png',missionHtml=results.map(r=>`<div style="display:flex;gap:9px;align-items:center;text-align:left;padding:8px 10px;border-radius:10px;background:${r.done?'#2c6b45':'#ffffff0b'}"><b>${r.done?'✓':'○'}</b><span>${r.label}</span></div>`).join('');overlay(`<img src="${SPRITE_ROOT}/actions/${action}" alt="${won?'ชนะ':'แพ้'}" style="width:150px;max-height:125px;object-fit:contain"><div class="eyebrow">${won?'DISCOVERY COMPLETE':'TRY AGAIN'}</div><h2>${won?'ผ่านด่านแล้ว!':'หมดแรงแล้ว!'}</h2><div style="font-size:30px;color:#ffc13f;margin:8px">${won?'★'.repeat(stars)+'☆'.repeat(3-stars):'☆☆☆'}</div><div style="display:grid;gap:6px;margin:12px 0">${missionHtml}</div><div class="result-grid"><div><b>${total}</b>คะแนน</div><div><b>${state.coins}</b>เหรียญ</div><div><b>${state.lives}</b>หัวใจ</div></div><button class="btn primary" id="again">${won&&active<19?'ด่านถัดไป ▶':'ลองอีกครั้ง'}</button><button class="btn" id="toMap">แผนที่ด่าน</button>`,()=>{$('#again').onclick=()=>start(won&&active<19?active+1:active);$('#toMap').onclick=()=>show('stages')})}
// Optional Supabase: set window.LOHD_SUPABASE={url,key} before this module to mirror scores.
async function syncCloud(){const c=window.LOHD_SUPABASE;if(!c?.url||!c?.key)return;try{await fetch(`${c.url}/rest/v1/leaderboard`,{method:'POST',headers:{apikey:c.key,Authorization:`Bearer ${c.key}`,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates'},body:JSON.stringify({name:save.name,score:save.best,level:save.unlocked})})}catch(e){console.info('Cloud sync unavailable; local save remains active.')}}
updateHome();renderStages();show('home');

